SELECT "Motos_2"."Anunciante__grupo_" AS "Anunciante__grupo_",   "Motos_2"."Marca" AS "Datos__copia_",   "Motos_2"."Medio" AS "Medio",   "Motos_2"."PrimeraLinea" AS "PrimeraLinea",   "Motos_2"."VER_ANUNCIO" AS "VER_ANUNCIO",   "Motos_2"."Vehiculo" AS "Vehiculo",   CAST(EXTRACT(MONTH FROM "Motos_2"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   SUM(CAST("Motos_2"."NumAnuncios" AS BIGINT)) AS "sum_NumAnuncios_ok",   CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Motos_2" WHERE ((CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) <= 2015) AND ('Cerrar' = 'Cerrar') AND (CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) = 2015) AND (CAST(EXTRACT(MONTH FROM "Motos_2"."FECHA") AS BIGINT) IN (9, 10, 11)) AND ("Motos_2"."Categoria" = 'MOTOCICLETAS')) GROUP BY "Motos_2"."Anunciante__grupo_",   "Motos_2"."Marca",   "Motos_2"."Medio",   "Motos_2"."PrimeraLinea",   "Motos_2"."VER_ANUNCIO",   "Motos_2"."Vehiculo",   "mn_FECHA_ok",   "yr_FECHA_ok";
